css:
:root {
  /* Florist Bouquet Theme - soft petals and ink outlines */
  --bg-primary: #fffaf8;
  --bg-alt: #fff1ec;
  --bg-hover: #ffe2d8;
  --text-primary: #2f1c1b;
  --text-secondary: #7c4a4a;
  --border: #f3b3b3;
  --accent: #e86a92;
  --accent-rgb: 232, 106, 146;
  --accent-hover: #d44f7b;
  --ink: #4f2a2a;
}

[data-theme="dark"] {
  --bg-primary: #1c1414;
  --bg-alt: #241a1a;
  --bg-hover: #2f2222;
  --text-primary: #ffeef0;
  --text-secondary: #f3b3b3;
  --border: #8d4c63;
  --accent: #ff7ba5;
  --accent-rgb: 255, 123, 165;
  --accent-hover: #ff96b8;
  --ink: #f3d7d9;
}

body {
  background: repeating-linear-gradient(45deg, rgba(var(--accent-rgb), 0.04) 0, rgba(var(--accent-rgb), 0.04) 12px, transparent 12px, transparent 24px), var(--bg-primary);
}

.card {
  border: 1px solid var(--border);
  background: linear-gradient(150deg, rgba(255, 255, 255, 0.9), rgba(255, 226, 216, 0.8));
  box-shadow: 0 12px 24px rgba(var(--accent-rgb), 0.15);
  position: relative;
}

.card::before {
  content: '✿';
  position: absolute;
  top: 8px;
  right: 12px;
  font-size: 18px;
  color: var(--accent);
  opacity: 0.6;
}

.tag {
  background: rgba(var(--accent-rgb), 0.12);
  border: 1px dashed var(--accent);
  color: var(--text-primary);
  font-weight: 600;
}
